import React from "react";
import '../../styles/timeSheet.css'
import TimeSheetHeader from "./TimeSheetHeader";
import TimeSheetWeekdays from "./TimeSheetWeekdays";
import TimeSheetDayList from "./TimeSheetDayList";

export default function TimeSheet({
    selectedDate,
    onDateChanged,
    onOpenPopupClicked,
    onActivityEditClicked,
    onActivityDeleteClicked,
    allActivities,
    activitiesForDay }) {

    return (
        <div className='timesheet-container'>
            <TimeSheetHeader
                onDateChanged={onDateChanged}
                selectedDate={selectedDate}
                onOpenPopupClicked={onOpenPopupClicked} />
            <TimeSheetWeekdays
                allActivities={allActivities}
                selectedDate={selectedDate}
                onDateChanged={onDateChanged} />
            <TimeSheetDayList
                onOpenPopupClicked={onOpenPopupClicked}
                onActivityEditClicked={onActivityEditClicked}
                onActivityDeleteClicked={onActivityDeleteClicked}
                activitiesForDay={activitiesForDay} />
        </div>
    );
}