import React from "react";

export default function ProjectItem({ onRemoveProject, item, onOpenSettingsPopup }) {
    return (
        <div className="project-list-item-container">
            <p>{item.name}</p>
            <p>{item.client}</p>
            <p>{item.developers.map((dev, idx) => dev.name + (idx < item.developers.length - 1 ? ", " : ''))}</p>
            <div className="flex-row">
                <div className="projects-item-action-buttons">
                    <button onClick={() => onOpenSettingsPopup(item)} className="timesheet-day-item-button active-button"><i className="fas fa-edit"></i></button>
                    <button onClick={() => onRemoveProject(item)} className="timesheet-day-item-button active-button"><i className="fas fa-trash-alt"></i></button>
                </div>
            </div>
        </div>
    )
}