import React, { useEffect, useState } from "react";
import '../../styles/timeSheet.css'
import { minutesToHours } from "../../utilities/minutesToHours";
import { calculateDate } from "../../utilities/calculateDate";

export default function DashbaordWeekdays({
    selectedDate,
    firstDate,
    allActivities,
    onDateChanged }) {

    const weekdays = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    const days = [];
    for (let i = 1; i <= 7; i++) {
        days.push(
            {
                name: weekdays[i - 1],
                date: calculateDate(firstDate, i - 1),
            }
        )
    }

    return (
        <div className="dashboard-day-container">
            <div className="dashboard-day-item">
                <p className="bold-font">Employee</p>
            </div>
            {
                days.map(day =>
                    <div key={day.name} className="dashboard-day-item">
                        <p className="bold-font">{day.name}</p>
                        <p>{day.date.toLocaleDateString('en-us', { month: "short", day: "numeric" })}</p>
                    </div>
                )
            }
            <div className="dashboard-day-item">
                <p className="bold-font">Week total</p>
            </div>
        </div>
    );
}
