import React from "react";
import '../../styles/timeSheet.css'
import { minutesToHours } from "../../utilities/minutesToHours";

export default function TimeSheetDayItem({
    activity,
    onActivityEditClicked,
    onActivityDeleteClicked }) {
    return (
        <div className="timesheet-day-list-item">
            <div className="timesheet-day-item-info">
                <p>{activity.title}</p>
                <p>{activity.project?.name}</p>
            </div>
            <div className="flex-row">
                <p>{minutesToHours(activity.minutes)}</p>

                <div className="timesheet-day-item-action-buttons">
                    {activity.project != null && <button onClick={() => onActivityEditClicked(activity)} className="timesheet-day-item-button active-button"><i className="fas fa-edit"></i></button>}
                    <button onClick={() => onActivityDeleteClicked(activity)} className="timesheet-day-item-button active-button"><i className="fas fa-trash-alt"></i></button>
                </div>
            </div>
        </div>
    );
}