import React, { useEffect, useState } from "react";
import ProjectSettingsPopup from "../popups/ProjectSettingsPopup";
import ProjectsList from "../projects/ProjectsList";
import ProjectsListHeader from "../projects/ProjectsListHeader";
import ProjectsHeader from "../projects/ProjectsHeader";
import axios from "axios";
import "../../styles/projects.css"

export default function ProjectsPage({ onDisplayAlert }) {

    const [isPopupOpen, setIsPopupOpen] = useState(false)
    const [project, setProject] = useState(null)
    const [developers, setDevelopers] = useState([])
    const [projects, setProjects] = useState([])

    useEffect(() => {
        axios.get(`${process.env.REACT_APP_API_ENDPOINT}/projects`)
            .then(response => response.data)
            .then(data => setProjects(data))
    }, [])

    useEffect(() => {
        axios.get(`${process.env.REACT_APP_API_ENDPOINT}/projects/developers`)
            .then(response => response.data)
            .then(data => {
                setDevelopers(data)
            });
    }, [])

    const handleDeleteProject = (project) => {
        if (window.confirm("Are you sure you want to remove this project?")) {
            {
                axios.delete(`${process.env.REACT_APP_API_ENDPOINT}/projects/${project.id}`)
                    .then(_ => {
                        setProjects(prevProjects => prevProjects.filter(x => x.id !== project.id));
                        onDisplayAlert("Succesfully removed the project")
                    })
            }
        }
    }

    const handleProjectAdded = (project) => {
        onDisplayAlert("Successfully added project")
        setProjects([...projects, project])
    }

    const handleProjectUpdated = (project) => {
        const index = projects.findIndex(x => x.id == project.id)
        onDisplayAlert("Successfully updated project")
        const updatedProjects = [...projects]
        updatedProjects[index] = project
        setProjects(updatedProjects)
    }

    const handleOnOpenSettingsPopup = (project) => {
        setIsPopupOpen(true)
        if (project)
            setProject(project)
        else
            setProject({
                name: '',
                client: '',
                minutes: 0,
                developers: []
            })
    }

    return (
        <>
            <div className="place-under-navigation-bar">
                <div className='projects-container'>
                    <ProjectsHeader onOpenSettingsPopup={handleOnOpenSettingsPopup} />
                    <ProjectsListHeader />
                    <ProjectsList projects={projects} onDeleteProject={handleDeleteProject} onOpenSettingsPopup={handleOnOpenSettingsPopup} />
                </div>
            </div>
            {
                project != null &&
                <ProjectSettingsPopup
                    developers={developers}
                    onProjectUpdated={handleProjectUpdated}
                    onProjectAdded={handleProjectAdded}
                    isPopupOpen={isPopupOpen}
                    project={project}
                    onClosePopupClicked={() => setIsPopupOpen(false)}
                />
            }
        </>
    )
}