import { React, useState, forwardRef, useEffect } from "react";
import '../../styles/timeSheet.css'
import DatePicker from "react-datepicker";

import "react-datepicker/dist/react-datepicker.css";
import { useParams } from "react-router-dom";

export default function TimeSheetHeader({
    onOpenPopupClicked,
    onDateChanged,
    selectedDate }) {

    let { developerId } = useParams();
    const [canEdit, setCanEdit] = useState(true)

    useEffect(() => {
        if (developerId) {
            setCanEdit(false)
        }
    }, [developerId])

    const handleDayChanged = (forward) => {
        var oldDate = new Date(selectedDate);
        oldDate.setDate(oldDate.getDate() + forward);
        onDateChanged(oldDate)
    }

    const CalendarButton = forwardRef(({ value, onClick }, ref) => (
        <button className="timesheet-header-calendar-button active-button" onClick={onClick} ref={ref}>
            <i className="fas fa-calendar" />
        </button>
    ));


    return (
        <div className="timesheet-header-container">
            <div className="flex-row">
                <div className="timesheet-header-navigation-buttons-frame">
                    <button onClick={() => handleDayChanged(-1)} className="timesheet-header-arrow-button active-button"><i className="fas fa-chevron-left"></i></button>
                    <button onClick={() => handleDayChanged(1)} className="timesheet-header-arrow-button active-button"><i className="fas fa-chevron-right"></i></button>
                </div>

                <h3 className="timesheet-header-date-text">{selectedDate.toLocaleDateString('en-us', { weekday: "long", year: "numeric", month: "short", day: "numeric" })}</h3>
            </div>
            <div className="flex-row">

                <DatePicker
                    customInput={<CalendarButton />}
                    selected={selectedDate}
                    onChange={(date) => onDateChanged(date)} />

                {canEdit &&
                    <button onClick={() => onOpenPopupClicked()} className="active-button timesheet-add-activity-button">Add activity</button>
                }
            </div>
        </div>
    );
}