import React from "react";

export default function Snackbar({ error, alert }) {
    return (
        <>
            {
                error != null ?
                    <div className={`snackbar ${error.isShown ? 'show' : ''}`}>{error.message}</div>
                    : <div className={`snackbar alert ${alert.isShown ? 'show' : ''}`}>{alert.message}</div>
            }
        </>
    )

}