import React from "react";
import '../../styles/timeSheet.css'
import TimeSheetDayItem from "./TimeSheetDayItem";

export default function TimeSheetDayList({
    activitiesForDay,
    onActivityEditClicked,
    onActivityDeleteClicked,
    onOpenPopupClicked }) {
    return (
        <div className="timesheet-day-item-list">
            {
                activitiesForDay.length > 0 ?
                    (
                        <div>
                            {
                                activitiesForDay.map((activity, i) => (
                                    <TimeSheetDayItem
                                        key={activity.id}
                                        onActivityEditClicked={onActivityEditClicked}
                                        onActivityDeleteClicked={onActivityDeleteClicked}
                                        activity={activity} />
                                ))
                            }
                        </div>
                    ) : (
                        <div className="timesheet-day-item-list-no-activities">
                            <p>You don't have any activities for this day yet.</p>
                            <button className="active-button timesheet-day-item-list-add-new-activity-button" onClick={onOpenPopupClicked}>Add activity</button>
                        </div>
                    )
            }
        </div>
    );
}