import React, { useEffect, useState } from "react";
import '../../styles/timeSheet.css'
import { minutesToHours } from "../../utilities/minutesToHours";
import { calculateDate } from "../../utilities/calculateDate";

export default function TimeSheetWeekdays({
    selectedDate,
    allActivities,
    onDateChanged }) {

    const selectedDayOfWeek = selectedDate.getDay() == 0 ? 7 : selectedDate.getDay();
    const [days, setDays] = useState([]);
    const [minutes, setMinutes] = useState(0)

    useEffect(() => {
        const weekdays = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
        const daysArray = [];
        setMinutes(0)
        for (let i = 1; i <= 7; i++) {

            let minutes = 0;
            let date = calculateDate(selectedDate, i - selectedDayOfWeek)
            let key = date.toDateString()

            if (allActivities.hasOwnProperty(key)) {
                for (let activiy of allActivities[key])
                    minutes += activiy.minutes
            }

            daysArray.push(
                {
                    name: weekdays[i - 1],
                    date: date,
                    minutes: minutes,
                }
            )

            setMinutes((prev) => prev + minutes)
        }

        setDays(daysArray)
    }, [allActivities, selectedDate])

    return (
        <div className="timesheet-day-container">
            {
                days.map((day, index) =>
                    <div key={day.name} onClick={() => onDateChanged(day.date)} className={`timesheet-day-item ${index + 1 == selectedDayOfWeek ? 'active' : ''}`}>
                        <p className={`${index + 1 == selectedDayOfWeek ? 'bold-font' : ''}`}>{day.name}</p>
                        <p>{minutesToHours(day.minutes)}</p>
                    </div>
                )
            }
            <div className="timesheet-day-item">
                <p className="bold-font">Week total</p>
                <p>{minutesToHours(minutes)}</p>
            </div>
        </div>
    );
}
