import React, { useContext, useEffect, useState } from "react";
import Modal from 'react-modal';
import { modalStyle } from "../../utilities/modalStyle";
import launchpadIcon from '../../images/launchpad-icon.png'
import axios from "axios";
import { UserContext } from "../../App";

export default function LoginPopup({
    onSuccessfullAuthentication,
    onClosePopupClicked,
    isPopupOpen }) {

    const ENV = process.env.NODE_ENV;
    const [isLogging, setIsLogging] = useState(true);
    const [registerError, setRegisterError] = useState('')
    const [loginError, setLoginError] = useState('')
    const user = useContext(UserContext)

    const defaultLoginCredentials =
    {
        email: ENV === "development" ? "admin@launchpad.com" : '',
        password: ENV === "development" ? "Test123@" : '',
    }

    const [loginForm, setLoginForm] = useState(defaultLoginCredentials);

    const [registerForm, setRegisterForm] = useState({
        name: "",
        email: "",
        password: ""
    });

    const handleClickSwitchToLogin = (isLogging) => {
        setIsLogging(isLogging)
    }

    const handleChangeLoginForm = (e) => {
        setLoginForm({
            ...loginForm,
            [e.target.name]: e.target.value
        });
    }

    const handleChangeRegisterForm = (e) => {
        setRegisterForm({
            ...registerForm,
            [e.target.name]: e.target.value
        });
    }

    useEffect(() => {
        setIsLogging(true)
        setRegisterForm({
            name: "",
            email: "",
            password: ""
        })
        setLoginForm(defaultLoginCredentials)
        setLoginError('')
        setRegisterError('')
    }, [isPopupOpen])

    const handleSubmitLogin = async (e) => {
        e.preventDefault();
        axios.post(`${process.env.REACT_APP_API_ENDPOINT}/auth/login`, JSON.stringify(loginForm), { headers: { 'Content-Type': 'application/json', }, })
            .then((response) => {
                saveUserToStorage(response.data)
                onSuccessfullAuthentication();
            })
            .catch((error) => {
                setLoginError(error.response.data.error)
            })
    }

    const handleSubmitRegister = async (e) => {
        e.preventDefault();
        axios.post(`${process.env.REACT_APP_API_ENDPOINT}/auth/register`, JSON.stringify(registerForm), { headers: { 'Content-Type': 'application/json', }, })
            .then((response) => {
                saveUserToStorage(response.data)
                onSuccessfullAuthentication();
            })
            .catch((error) => {
                setRegisterError(error.response.data.errors[0].description)
            })
    }

    const saveUserToStorage = (user) => {
        localStorage.setItem("user", JSON.stringify(user));
        axios.defaults.headers.common = { 'Authorization': `Bearer ${user.token}` }
    }

    return (
        <Modal
            isOpen={isPopupOpen}
            appElement={document.getElementById('root')}
            style={modalStyle}>
            <div className="popup-main-container">
                <div className='popup-header-container'>
                    <img className='popup-icon' src={launchpadIcon} />
                    <h3 className='pupup-title'>{isLogging ? 'Login' : 'Register'}</h3>
                    {user &&
                        <i onClick={() => onClosePopupClicked()} className="fas fa-times popup-close-button"></i>
                    }
                </div>
                <hr />
                {
                    isLogging ?
                        (
                            <form onSubmit={handleSubmitLogin} className="login-popup-main-div-content">
                                <div className='popup-main-container-content'>
                                    {(loginError?.length ?? 0) > 0 && <p className='error-msg'>{loginError}</p>}

                                    <p className='popup-main-container-label'>Email</p>
                                    <div className='underline' />
                                    <input required type="email" placeholder='Type your email' name='email' value={loginForm.email} onChange={handleChangeLoginForm} className='addActivity-popup-title' />

                                    <p className='popup-main-container-label'>Password</p>
                                    <div className='underline' />
                                    <input required type="password" placeholder='Type your password' name='password' value={loginForm.password} onChange={handleChangeLoginForm} className='addActivity-popup-title' />

                                </div>
                                <div className="align-bottom">
                                    <button className="active-button">Login</button>
                                    <div className='login-separator-div'>
                                        <hr />
                                        <p>No account yet?</p>
                                        <hr />
                                    </div>
                                    <p onClick={() => handleClickSwitchToLogin(false)} className="clickable-p">Click to create an account</p>
                                    <br />
                                </div>
                            </form>
                        )
                        : (
                            <form onSubmit={handleSubmitRegister} className="login-popup-main-div-content">
                                <div className='popup-main-container-content'>
                                    {registerError.length > 0 && <p className='error-msg'>{registerError}</p>}
                                    <p className='popup-main-container-label'>Name</p>
                                    <div className='underline' />
                                    <input required type="name" placeholder='Type your name' name='name' value={registerForm.name} onChange={handleChangeRegisterForm} className='addActivity-popup-title' />


                                    <p className='popup-main-container-label'>Email</p>
                                    <div className='underline' />
                                    <input required type="email" placeholder='Type your email' name='email' value={registerForm.email} onChange={handleChangeRegisterForm} className='addActivity-popup-title' />

                                    <p className='popup-main-container-label'>Password</p>
                                    <div className='underline' />
                                    <input required type="password" placeholder='Type your password' name='password' value={registerForm.password} onChange={handleChangeRegisterForm} className='addActivity-popup-title' />

                                </div>
                                <div className="align-bottom">
                                    <button className="active-button">Register</button>
                                    <div className='login-separator-div'>
                                        <hr />
                                        <p>Already have an account?</p>
                                        <hr />
                                    </div>
                                    <p onClick={() => handleClickSwitchToLogin(true)} className="clickable-p">Click to login</p>
                                    <br />
                                </div>
                            </form>
                        )
                }
            </div>
        </Modal>
    );
}