import React, { useEffect, useState } from "react";
import Dashboard from "../dashboard/Dashboard";
import axios from "axios";
import { calculateDate } from "../../utilities/calculateDate";

export default function DashboardPage() {

    const [selectedDate, setSelectedDate] = useState(new Date());

    const selectedDayOfWeek = selectedDate.getDay() == 0 ? 7 : selectedDate.getDay();
    const firstDateOfWeek = calculateDate(selectedDate, 1 - selectedDayOfWeek)
    const [developersWeek, setDevelopersWeek] = useState([])

    const handleDateChanged = (date) => {
        setSelectedDate(date)
    }

    useEffect(() => {
        const formattedDate = firstDateOfWeek.toLocaleDateString('en-us', { year: "numeric", month: "2-digit", day: "2-digit" });
        axios.get(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes/dashboard?date=${formattedDate}`)
            .then(result => result.data)
            .then(data => {
                console.log(data)
                setDevelopersWeek(data)
            });
    }, [selectedDate])

    return (
        <div className="place-under-navigation-bar">
            <Dashboard
                firstDateOfWeek={firstDateOfWeek}
                onDateChanged={handleDateChanged}
                developersWeek={developersWeek}
                selectedDate={selectedDate} />
        </div>
    )
}