import { React, useState } from "react";

export default function NumberSelector({ maxValue, onChange, value }) {

    return (
        <select value={value} onChange={(e) => onChange(e.target.value)} className="bold-font" >
            {
                Array.from(Array(maxValue).keys()).map(number =>
                    <option className="bold-font" value={number}>{number}</option>
                )
            }
        </select >
    );

}