import React, { useEffect, useState } from 'react';
import { modalStyle } from '../../utilities/modalStyle';
import Modal from 'react-modal';
import '../../styles/popups.css'

import launchpadIcon from '../../images/launchpad-icon.png'
import NumberSelector from '../../utilities/NumberSelector';

export default function AddActivityPopup({
    isPopupOpen,
    onClosePopupClicked,
    onDataSubmited,
    projects,
    activity }) {

    const [formData, setFormData] = useState({ ...activity })

    useEffect(() => {
        if (isPopupOpen) {
            setFormData({ ...activity })
        }
    }, [isPopupOpen])

    const handleDataSubmited = (e) => {
        e.preventDefault()
        onDataSubmited(formData)
        onClosePopupClicked()
    }

    const handleValueChange = (event) => {
        setFormData(
            {
                ...formData,
                [event.target.name]: event.target.value
            })
    }

    return (
        <Modal
            isOpen={isPopupOpen}
            appElement={document.getElementById('root')}
            style={modalStyle}>
            <div className='popup-main-container'>
                <div className='popup-header-container'>
                    <img className='popup-icon' src={launchpadIcon} />
                    <h3 className='pupup-title'>Add a new activity</h3>
                    <i onClick={() => onClosePopupClicked()} className="fas fa-times popup-close-button"></i>
                </div>
                <hr />

                <form onSubmit={handleDataSubmited}>
                    <div className='popup-main-container-content'>

                        <p className='popup-main-container-label'>Time worked on</p>
                        <div className='underline' />
                        <TimePicker minutes={activity.minutes} onChange={handleValueChange} />

                        <p className='popup-main-container-label'>Title</p>
                        <div className='underline' />
                        <input required placeholder='Type the title' name='title' value={formData.title} onChange={handleValueChange} className='addActivity-popup-title' />

                        <p className='popup-main-container-label'>Project worked on</p>
                        <div className='underline' />
                        <div className='addActivity-popup-project-box'>
                            <select style={{ color: formData.project == "" ? "#858585" : "white" }} required name='projectId' value={formData.project.id} onChange={handleValueChange} className='addActivity-project-select'>
                                <option value="" disabled selected>Select the project</option>
                                {projects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}
                            </select>
                        </div>
                    </div>

                    <button className="active-button align-bottom">Submit</button>
                </form>
            </div>
        </Modal>
    );
}

const TimePicker = ({ onChange, minutes }) => {

    const [time, setTime] = useState({
        hoursTens: Math.floor(minutes / 600),
        hours: Math.floor(minutes % 600 / 60),
        minutesTens: Math.floor(minutes % 60 / 10),
        minutes: Math.floor(minutes % 60 % 10),
    })

    const handleOnChange = (type, value) => {
        setTime((prevTime) => {
            const updatedTime = {
                ...prevTime,
                [type]: Number(value)
            };

            onChange({
                target: {
                    name: 'minutes',
                    value:
                        updatedTime.hoursTens * 10 * 60 +
                        updatedTime.hours * 60 +
                        updatedTime.minutesTens * 10 +
                        updatedTime.minutes
                }
            });

            return updatedTime;
        });
    }

    return (
        <div className='addActivity-popup-time-picker-container'>
            <div className='addActivity-popup-time-picker-cell'>
                <NumberSelector value={time.hoursTens} onChange={(value) => handleOnChange("hoursTens", value)} maxValue={10} />
            </div>

            <div className='addActivity-popup-time-picker-cell'>
                <NumberSelector value={time.hours} onChange={(value) => handleOnChange("hours", value)} maxValue={10} />
            </div>

            <h3>:</h3>

            <div className='addActivity-popup-time-picker-cell'>
                <NumberSelector value={time.minutesTens} onChange={(value) => handleOnChange("minutesTens", value)} maxValue={6} />
            </div>

            <div className='addActivity-popup-time-picker-cell'>
                <NumberSelector value={time.minutes} onChange={(value) => handleOnChange("minutes", value)} maxValue={10} />
            </div>
        </div>
    )
}
