import React, { useContext, useState } from "react"
import { Link } from "react-router-dom";
import logo from "../images/launchpad-logo.svg"
import "../styles/navigationBar.css"
import { UserContext } from "../App";

export const NavigationBar = ({
    onClickInvite,
    onChangeUserSession, }) => {

    const user = useContext(UserContext)
    const [isMenuOpen, setIsMenuOpen] = useState(false)

    const loginClick = () => {
        setIsMenuOpen(false);
        onChangeUserSession();
    }

    const handleMenuClick = () => {
        setIsMenuOpen(!isMenuOpen)
    }

    const menuItems = (
        <div className="nav-logged-in">
            {user &&
                <>
                    {user.role == "Admin" && (
                        <>
                            <Link to="launchpadtimetracker/projects"><p className="clickable-p">Projects</p></Link>
                            <p className="nav-logged-in-separator">|</p>
                            <p className="clickable-p" onClick={onClickInvite}>Invite</p>
                            <p className="nav-logged-in-separator">|</p>
                            <Link to="launchpadtimetracker/dashboard"><p className="clickable-p">Dashboard</p></Link>
                            <p className="nav-logged-in-separator">|</p>
                        </>
                    )}
                    <div className="profile-options">
                        <p>{user.name}</p>
                        <div className="dropdown-content">
                            <p className="clickable-p" onClick={loginClick}>Logout</p>
                        </div>
                    </div>
                </>
            }
        </div>
    )
    return (
        <>
            <nav>
                <Link to='launchpadtimetracker/'>
                    <div className="logo-container">
                        <img src={logo} />
                    </div>
                </Link>

                <div className="nav-mobile-menu">
                    <p className="clickable-p" onClick={handleMenuClick}><i className="fas fa-bars"></i></p>
                </div>

                <div id="nav-desktop-menu">
                    {menuItems}
                </div>
            </nav>
            <div className={`nav-side-bar ${isMenuOpen ? "nav-side-bar-show" : null}`}>
                {menuItems}
            </div>
        </>
    )
}