import { React, useState, forwardRef, useEffect } from "react";
import '../../styles/timeSheet.css'
import DatePicker from "react-datepicker";

import "react-datepicker/dist/react-datepicker.css";
import { calculateDate } from "../../utilities/calculateDate";

export default function DashboardHeader({
    onDateChanged,
    firstDate,
    selectedDate }) {

    const handleDayChanged = (forward) => {
        var oldDate = new Date(selectedDate);
        oldDate.setDate(oldDate.getDate() + forward);
        onDateChanged(oldDate)
    }


    const CalendarButton = forwardRef(({ value, onClick }, ref) => (
        <button className="timesheet-header-calendar-button active-button" onClick={onClick} ref={ref}>
            <i className="fas fa-calendar" />
        </button>
    ));

    const monday = firstDate.toLocaleDateString('en-us', { month: "short", day: "numeric" })
    const sunday = calculateDate(firstDate, 6).toLocaleDateString('en-us', { year: "numeric", month: "short", day: "numeric" })

    return (
        <div className="timesheet-header-container">
            <div className="flex-row">
                <div className="timesheet-header-navigation-buttons-frame">
                    <button onClick={() => handleDayChanged(-7)} className="timesheet-header-arrow-button active-button"><i className="fas fa-chevron-left"></i></button>
                    <button onClick={() => handleDayChanged(7)} className="timesheet-header-arrow-button active-button"><i className="fas fa-chevron-right"></i></button>
                </div>

                <h3 className="timesheet-header-date-text">{`${monday} - ${sunday}`}</h3>
            </div>
            <div className="flex-row">

                <DatePicker
                    customInput={<CalendarButton />}
                    selected={selectedDate}
                    onChange={(date) => onDateChanged(date)} />
            </div>
        </div>
    );
}