import React, { useState, useRef, useEffect } from "react";
import Modal from 'react-modal';
import launchpadIcon from '../../images/launchpad-icon.png'
import { modalStyle } from "../../utilities/modalStyle";
import axios from "axios";


export default function ProjectSettingsPopup({
    onClosePopupClicked,
    onProjectAdded,
    onProjectUpdated,
    developers,
    project,
    isPopupOpen }) {

    const [projectToEdit, setProjectToEdit] = useState(project)
    const [isNewProject, setIsNewProject] = useState(false)

    useEffect(() => {
        setProjectToEdit(project)
        setIsNewProject(project.name == '')
    }, [isPopupOpen])

    const handleAddProject = (e) => {
        e.preventDefault()

        const projectDto = {
            client: projectToEdit.client,
            name: projectToEdit.name,
            developersIds: projectToEdit.developers.map(x => x.id)
        }

        if (isNewProject) {
            axios.post(`${process.env.REACT_APP_API_ENDPOINT}/projects`, JSON.stringify(projectDto), { headers: { 'Content-Type': 'application/json', }, })
                .then(response => response.data)
                .then(data => {
                    onClosePopupClicked()
                    onProjectAdded(data)
                })
                .catch((error) => {
                    console.log(error)
                })
        }
        else {
            projectDto.id = projectToEdit.id;
            axios.put(`${process.env.REACT_APP_API_ENDPOINT}/projects`, JSON.stringify(projectDto), { headers: { 'Content-Type': 'application/json', }, })
                .then(response => response.data)
                .then(data => {
                    onClosePopupClicked()
                    onProjectUpdated(data)
                })
                .catch((error) => {
                    console.log(error)
                })

        }
    }

    const modalCustomStyle = useRef({
        ...modalStyle,
        content: {
            ...modalStyle.content,
            minHeight: "350px",
            height: "60vh"
        }
    })

    const handleInputChange = (e, developer) => {
        if (e.target.checked && projectToEdit != null) {
            const updatedDevelopers = [...projectToEdit.developers, developer]
            setProjectToEdit({
                ...projectToEdit,
                developers: updatedDevelopers
            })
        }
        else {
            setProjectToEdit({
                ...projectToEdit,
                developers: projectToEdit.developers.filter(dev => dev.id != developer.id)
            })
        }
    }

    const handleValueChange = (e) => {
        setProjectToEdit({
            ...projectToEdit,
            [e.target.name]: e.target.value
        })
    }

    return (
        <Modal
            isOpen={isPopupOpen}
            appElement={document.getElementById('root')}
            style={modalCustomStyle.current}>
            <div className='popup-main-container'>
                <div className='popup-header-container'>
                    <img className='popup-icon' src={launchpadIcon} />
                    <h3 className='pupup-title'>Project settings</h3>
                    <i onClick={() => { onClosePopupClicked() }} className="fas fa-times popup-close-button"></i>
                </div>
                <hr />

                <form className="project-settings-form" onSubmit={handleAddProject}>
                    <div className="popup-settings-content">
                        <div>
                            <p className='popup-main-container-label'>Client</p>
                            <div className='underline' />
                            <input required type="text" placeholder='Type the client' name='client' value={projectToEdit?.client} onChange={handleValueChange} className='addActivity-popup-title' />

                            <p className='popup-main-container-label'>Project</p>
                            <div className='underline' />
                            <input required type="text" placeholder='Type a project' name='name' value={projectToEdit?.name} onChange={handleValueChange} className='addActivity-popup-title' />

                            <p className='popup-main-container-label'>Developers</p>
                            <div className='underline' />
                            <div key={projectToEdit.id}>
                                {
                                    projectToEdit &&
                                    developers?.map((developer) =>
                                    (
                                        <div className="developer-div">
                                            <input onChange={(e) => handleInputChange(e, developer)} defaultChecked={projectToEdit.developers.some(dev => dev.id == developer.id)} className="developer-div-input" type="checkbox" />
                                            <p>{developer.name}</p>

                                        </div>
                                    ))
                                }
                            </div>
                        </div>
                    </div>

                    <button className="active-button">{isNewProject ? 'Add project' : 'Save changes'}</button>

                </form>

            </div>
        </Modal>
    );
}