import { React, useContext, useEffect, useState } from "react";
import '../../styles/timeSheet.css'
import '../../styles/snackbar.css'
import AddActivityPopup from "../popups/AddActivityPopup";
import TimeSheet from "../timeSheet/TimeSheet";
import Snackbar from "../../utilities/Snackbar";
import { mockActivities } from "../../data/mockActivities";
import { mockProjects } from "../../data/mockProjects";
import axios from "axios";
import { UserContext } from '../../App'
import { useParams } from "react-router-dom";

export default function TimePage({ onDisplayAlert }) {

    const initialActivity = {
        title: "",
        project: {},
        minutes: 0
    }

    const user = useContext(UserContext)

    const [selectedDate, setSelectedDate] = useState(new Date());

    const [isPopupOpen, setIsPopupOpen] = useState(false);

    const [activityToEdit, setActivityToEdit] = useState(initialActivity)

    const [allActivities, setAllActivities] = useState(mockActivities)

    const [activitiesForDay, setActivitiesForDay] = useState([])

    const [projects, setProjects] = useState([])

    const [userId, setUserId] = useState(null)

    const { developerId } = useParams();

    useEffect(() => {
        setUserId(developerId ? developerId : user.id)
    }, [developerId])

    useEffect(() => {
        if (userId) {
            console.log(process.env.NODE_ENV)
            console.log(process.env.REACT_APP_API_ENDPOINT)
            console.log(process.env.PUBLIC_URL)
            axios.get(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes/projects/${userId}`)
                .then(response => response.data)
                .then(data => setProjects(data))

            axios.get(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes/${userId}`)
                .then(response => response.data)
                .then(data => {
                    let activities = {};
                    for (let activity of data) {
                        let key = new Date(Date.parse(activity.date)).toDateString()
                        if (!activities.hasOwnProperty(key))
                            activities[key] = []

                        activities[key].push(activity)
                    }
                    setAllActivities(activities)
                })
        }
    }, [userId])


    useEffect(() => {
        const key = selectedDate.toDateString()
        const list = allActivities.hasOwnProperty(key) ? allActivities[key] : []
        setActivitiesForDay(list)
    }, [selectedDate, allActivities])

    const handleOnActivityEditClicked = (activity) => {
        setActivityToEdit(activity)
        setIsPopupOpen(true)
    }

    const handleOpenPopupClicked = () => {
        setIsPopupOpen(true)
    }

    const handleClosePopupClicked = () => {
        setIsPopupOpen(false)
        setActivityToEdit(initialActivity)
    }

    const handleActivityDeleted = (activity) => {
        if (window.confirm("Are you sure you want to remove this project?")) {
            {
                axios.delete(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes/${activity.id}`)
                    .then(result => result.data)
                    .then(data => {
                        let updatedActivitiesForDay = activitiesForDay.filter(obj => obj.id != activity.id);
                        updateActivitiesForDay(updatedActivitiesForDay)
                        onDisplayAlert("Successfully deleted!")
                    })
            }
        }
    }

    const handleDataSubmited = (activity) => {
        let updatedActivitiesForDay = []

        const trackedTimeDto = {
            title: activity.title,
            developerId: user.id,
            projectId: activity.hasOwnProperty("projectId") ? activity.projectId : activity.project.id,
            minutes: activity.minutes,
            date: selectedDate
        }

        if (activitiesForDay.some(obj => obj.id == activity.id)) {
            trackedTimeDto.id = activity.id
            axios.put(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes`, JSON.stringify(trackedTimeDto), { headers: { 'Content-Type': 'application/json', }, })
                .then(response => response.data)
                .then(data => {
                    updatedActivitiesForDay = activitiesForDay.map(obj => obj.id == data.id ? data : obj)
                    console.log(data)
                    updateActivitiesForDay(updatedActivitiesForDay)
                    onDisplayAlert("Successfully updated!")
                })
                .catch((error) => {
                    console.log(error)
                })

        }
        else {
            axios.post(`${process.env.REACT_APP_API_ENDPOINT}/trackedTimes`, JSON.stringify(trackedTimeDto), { headers: { 'Content-Type': 'application/json', }, })
                .then(response => response.data)
                .then(data => {
                    updatedActivitiesForDay = [...activitiesForDay, data]
                    updateActivitiesForDay(updatedActivitiesForDay)
                    setActivityToEdit(initialActivity)
                    onDisplayAlert("Successfully added!")
                })
                .catch((error) => {
                    console.log(error)
                })
        }

    }

    const handleDateChanged = (date) => {
        setSelectedDate(date)
    }

    function updateActivitiesForDay(updatedActivitiesForDay) {
        setAllActivities({ ...allActivities, [selectedDate.toDateString()]: updatedActivitiesForDay })
        setActivitiesForDay(updatedActivitiesForDay)
    }

    return (
        <div className="place-under-navigation-bar">
            <TimeSheet
                selectedDate={selectedDate}
                allActivities={allActivities}
                activitiesForDay={activitiesForDay}
                onDateChanged={handleDateChanged}
                onActivityDeleteClicked={handleActivityDeleted}
                onActivityEditClicked={handleOnActivityEditClicked}
                onOpenPopupClicked={handleOpenPopupClicked} />

            <AddActivityPopup
                projects={projects}
                onDataSubmited={handleDataSubmited}
                activity={activityToEdit}
                onClosePopupClicked={handleClosePopupClicked}
                isPopupOpen={isPopupOpen} />
        </div>
    );
}