import React from "react";
import { calculateDate } from "../../utilities/calculateDate";
import { minutesToHours } from "../../utilities/minutesToHours";
import { Link } from "react-router-dom";

export default function DashboardWeekItem({
    data,
    firstDate }) {

    console.log(firstDate)
    const dates = [];
    let totalHours = 0;
    for (let i = 0; i <= 6; i++) {
        const date = calculateDate(firstDate, i).toLocaleDateString('en-us', { year: "2-digit", month: "2-digit", day: "2-digit" });
        let minutes = 0;
        if (data.value.days.hasOwnProperty(date))
            minutes = data.value.days[date];

        totalHours += minutes;
        dates.push(minutes)
    }

    return (
        <Link to={`../launchpadtimetracker/${data.key}`} >
            <div className="dashboard-list-item-container">
                <p>{data.value.name}</p>
                {dates.map(minutes => (
                    <p>{minutesToHours(minutes)}</p>
                ))}
                <p>{minutesToHours(totalHours)}</p>
            </div>
        </Link>

    )
}