import React from "react";
import ProjectItem from "./ProjectItem";

export default function ProjectsList({ projects, onDeleteProject, onOpenSettingsPopup }) {
    return (
        <div className="projects-day-activity-list">
            {
                projects.map(item => <ProjectItem
                    onRemoveProject={onDeleteProject}
                    onOpenSettingsPopup={onOpenSettingsPopup}
                    item={item} />)
            }
        </div>
    )
}