import React, { useState, useRef, useEffect } from "react";
import Modal from 'react-modal';
import launchpadIcon from '../../images/launchpad-icon.png'
import { modalStyle } from "../../utilities/modalStyle";
import Snackbar from '../../utilities/Snackbar';
import axios from "axios";


export default function InvitePopup({
    onClosePopup,
    onSuccessfullyInvited,
    isPopupOpen }) {

    const modalCustomStyle = useRef({
        ...modalStyle,
        content: {
            ...modalStyle.content,
            minHeight: "350px",
            height: "60vh"
        }
    })

    const [error, setError] = useState('')

    const [developer, setDeveloper] = useState({
        name: '',
        email: ''
    })

    const handleChangeForm = (e) => {
        setDeveloper(
            {
                ...developer,
                [e.target.name]: e.target.value
            });
    }

    const handleSubmitInvitation = (e) => {
        e.preventDefault();
        axios.post(`${process.env.REACT_APP_API_ENDPOINT}/auth/invite`, JSON.stringify(developer), { headers: { 'Content-Type': 'application/json', }, })
            .then(_ => {
                onClosePopup()
                onSuccessfullyInvited()
            })
            .catch((error) => setError(error?.response?.data?.error))
    }

    useEffect(() => {
        setDeveloper({
            name: '',
            email: ''
        })
        setError('')
    }, [isPopupOpen])

    return (
        <Modal
            isOpen={isPopupOpen}
            appElement={document.getElementById('root')}
            style={modalCustomStyle.current}>
            <div className='popup-main-container'>
                <div className='popup-header-container'>
                    <img className='popup-icon' src={launchpadIcon} />
                    <h3 className='pupup-title'>Invite a developer</h3>
                    <i onClick={onClosePopup} className="fas fa-times popup-close-button"></i>
                </div>
                <hr />
                <form onSubmit={handleSubmitInvitation}>
                    <div className='popup-main-container-content'>
                        {error.length > 0 && <p className='error-msg'>{error}</p>}
                        <p className='popup-main-container-label'>Name</p>
                        <div className='underline' />
                        <input required type="text" placeholder='Type a name' name='name' onChange={handleChangeForm} className='addActivity-popup-title' />

                        <p className='popup-main-container-label'>Email</p>
                        <div className='underline' />
                        <input required type="email" placeholder='Type an email' name='email' onChange={handleChangeForm} className='addActivity-popup-title' />
                    </div>

                    <button className="active-button align-bottom">Submit</button>
                </form>
            </div>
        </Modal>
    );
}