import React, { useState, useContext, createContext, useEffect } from 'react'
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { NavigationBar } from './utilities/NavigationBar';
import TimePage from './components/routerPages/TimePage';
import "./styles/styles.css"
import InvitePopup from './components/popups/InvitePopup';
import LoginPopup from './components/popups/LoginPopup';
import DashboardPage from './components/routerPages/DashboardPage';
import ProjectsPage from './components/routerPages/ProjectsPage';
import Snackbar from './utilities/Snackbar';
import axios from 'axios';

export const UserContext = createContext(null)

export const App = () => {

    const [isLoginPopupOpen, setIsLoginPopupOpen] = useState(false);
    const [isInvitePopupOpen, setIsInvitePopupOpen] = useState(false);
    const [user, setUser] = useState(null);

    const initialAlert = {
        isShown: false,
        message: "",
        timeoutId: ""
    }

    useEffect(() => {
        getUser()
    }, [])

    useEffect(() => {

    }, [user])

    const [alert, setAlert] = useState(initialAlert);

    function displayAlert(message) {
        clearTimeout(alert.timeoutId)
        setAlert({
            isShown: true,
            message: message,
            timeoutId: setTimeout(() => {
                setAlert(initialAlert)
            }, 3000)
        });
    }

    const handleClosePopup = (popup) => {
        if (popup == "loginPopup")
            setIsLoginPopupOpen(false)
        else if (popup == "invitePopup")
            setIsInvitePopupOpen(false)
    }

    const handleClickInvite = () => {
        setIsInvitePopupOpen(true)
    }

    const handleSuccessfullAuthentication = () => {
        setIsLoginPopupOpen(false)
        getUser()
    }

    const getUser = () => {
        if (user != null)
            return;

        const userJson = localStorage.getItem("user");
        if (userJson != null) {
            const usr = JSON.parse(userJson)
            setUser(usr);
            axios.defaults.headers.common = { 'Authorization': `Bearer ${usr.token}` }
        }
        else
            setIsLoginPopupOpen(true)
    }


    const handleChangeUserSession = () => {
        if (user != null) {
            axios.defaults.headers.common = null
            axios.get(`${process.env.REACT_APP_API_ENDPOINT}/auth/logout`);
            localStorage.removeItem("user");
            setUser(null);
            setIsLoginPopupOpen(true)
        }
    }

    return (
        <UserContext.Provider value={user}>
            <NavigationBar
                onClickInvite={handleClickInvite}
                onChangeUserSession={handleChangeUserSession} />

            {user &&
                <Routes>
                    <Route path='launchpadtimetracker/:developerId?' element={<TimePage onDisplayAlert={(msg) => displayAlert(msg)} />} />
                    <Route path='launchpadtimetracker/dashboard' element={<DashboardPage />} />
                    <Route path='launchpadtimetracker/projects' element={<ProjectsPage onDisplayAlert={(msg) => displayAlert(msg)} />} />
                </Routes>
            }

            <LoginPopup
                isPopupOpen={isLoginPopupOpen}
                onSuccessfullAuthentication={handleSuccessfullAuthentication}
                onClosePopupClicked={() => handleClosePopup("loginPopup")}
            />

            <InvitePopup
                isPopupOpen={isInvitePopupOpen}
                onSuccessfullyInvited={() => displayAlert("An invitation has been sent")}
                onClosePopup={() => { handleClosePopup("invitePopup") }} />

            <Snackbar alert={alert} />
        </UserContext.Provider>
    )
}